import React, { Fragment, useContext } from 'react';

import style from "./yourTeam.module.css" ;
import { UserContext } from '../../Context/UserContext.js';
import TimeAgo from "../TimeAgo/TimeAgo.jsx"
import { Link } from 'react-router-dom';
import avatar from "../../Assets/images/profile1.png"



export default function YourTeam() {
   const {team} = useContext(UserContext) ;




   return (
      <Fragment>
         <div className='container'>
            <h1 className='main-header'>Team Member Options</h1>
            <div className='mt-5 '>
               {team.length > 0 ? 
                  team.map((ele)=>
                     <Link key={ele._id} to={`/SpecificUser/${ele._id}`} className='card btn my-1'>
                        <div className=" my-2">
                              <div className="row p-1 align-items-center" >
                                 <div className="col-3">
                                    <img src={ele.image?.secure_url || avatar} className={`img-fluid rounded-start  ${style.cardImage}`} alt="..." />
                                 </div>

                                 <div className="col-9 p-0">
                                    <div className={`card-body p-0 ${style.text}`}>
                                       <h6 className="card-title p-0 m-0">{ele.name} </h6>
                                       <p className="card-text p-0 m-0">Branch : {ele.branch?.name} </p>
                                       <p className='p-0 m-0'> <TimeAgo createdAt={ele.createdAt}/></p>
                                    </div>
                                 </div>
                              </div>
                        </div>
                     </Link>
                  ) 
                  : 
                  <h4>Not Exist Team Member. !</h4>
               }
               
            </div>
         </div>
      </Fragment>
   )
}










