import React, { Fragment, useContext, useEffect, useState } from 'react';
import TimeAgo from '../TimeAgo/TimeAgo.jsx';
import UploadOrderImage from '../UploadOrderImage/UploadOrderImage.jsx';
import style from "./orderLoggedBranch.module.css" ;
import { OrderContext } from '../../Context/OrderContext.js';
import Swal from 'sweetalert2';






export default function OrderLoggedBranch() {
      const[status , setStatus] = useState("")
      const {getLoggedOrders , orders} = useContext(OrderContext) ;
      


      function handleSearch(search){
         if(search.length > 3){
            getLoggedOrders(search) ;
         }else{
            getLoggedOrders("") ;
         }
      }



   const showImageProfile = (url)=>{
      Swal.fire({
         imageUrl:  url ,
         imageHeight: 700,
         imageAlt: "A tall image"
      });
   }


   useEffect(() => {
      getLoggedOrders("") ;
   }, [])

   return (
      <Fragment>
         <div className='container'>
            <h1 className='main-header my-4'>جميع الطلبيات السابقة </h1>

            <div className="mb-5">
               <form >
                  <div className='position-relative'>
                     <input  type="search" onChange={(e) => handleSearch(e.target.value)}  className='form-control' id='search' placeholder='Search Order more than 3 char'  name="search" />
                  </div>
               </form>
            </div>

            {
               orders.length? 
                  orders.map((ele)=>
                     <div key={ele._id} className={`${style.orderCart} container border border-2 rounded-2 my-3 p-0`}>
                        <div className={`${style.title} row align-item-center mx-2`}>
                           <p className='col-6 text-danger'>{ele.title}</p>
                           <p className='col-3 text-danger'>{ele.delivery_number}</p>
                           <p className='col-1 text-danger'>{ele.itemNumber}</p>
                           <p className='col-2 p-0 m-0 '>
                              <TimeAgo createdAt={ele.createdAt} showTimeOnly={true}/>
                           </p>
                        </div>


                           <div>
                              <details className='text-center'>
                                 <p>Created At : {new Date(ele.createdAt).toISOString().slice(0, 10)}</p>
                                 <summary className={`m-auto w-50 bg-main mb-1`} >Details <span className='d-inline-block mx-3'>{ele.orderItems.length}</span></summary>
                                 <div className={`${style.cardItems} `}>
                                    <table className="table order-table table-sm ">
                                       <thead>
                                          <tr>
                                             <th>Item</th>
                                             <th>Code</th>
                                             <th>Quantity</th>
                                             <th>Expired</th>
                                          </tr>
                                       </thead>
                                       <tbody>
                                          {ele.orderItems.map((order) => (
                                             <tr key={order.itemName}>
                                             <td>{order.itemName}</td>
                                             <td>{order.item_s_code}</td>
                                             <td>{order.item_quantity}</td>
                                             <td>{new Date(order.expired_date).toISOString().slice(0, 10)}</td>
                                             </tr>
                                          ))}
                                       </tbody>
                                    </table>


                                    <div>
                                       <button onClick={()=>{setStatus("add")}} className={`btn btn-outline-primary btn-sm m-1 p-0 ${style.showBtn}`}>Add Images</button>
                                       <button onClick={()=>{setStatus("display")}} className={`btn btn-outline-success btn-sm m-1 p-0 ${style.showBtn}`}>Show Images</button>
                                    </div>
                                    {status === "add"? 
                                       <div>
                                          <UploadOrderImage orderId={ele._id}/>
                                       </div> : ""
                                    }
                                    {status === "display"? 
                                       <div>
                                          <div className='overflow-scroll py-3 px-2' style={{ display: 'flex', gap: '10px'}}>
                                             {ele.images.length? ele.images.map(({secure_url}, i) => (
                                                <img key={i} src={secure_url} alt={`orderImage-${i}`} width={150} 
                                                   onClick={()=>{showImageProfile(secure_url)}}
                                                   onError={(e) => {
                                                      e.target.onerror = null ; // علشان ميعملش loop
                                                   }}
                                                />
                                             )) : <p className='col-12 text-danger fs-6 fw-bold'>لا يوجد اى صور خاصة بهذة الطلبية لعرضها</p>}
                                          </div>
                                       </div> : "" 
                                    }
                                 </div>
                              </details>
                           </div>
                     </div>
                  )
               : ""
            }

         </div>
      </Fragment>
   )
}
